mapper.select:
SELECT * FROM t_model tm where tm.is_delete = 0
and tm.model_bot_type = #{modelBotType}
ORDER BY tm.update_date DESC

select tm.*, ep.experiment_name as experiment_plan_name, ep.experiment_title as experiment_plan_title, case when f.id is not null then 1 else 0 end as is_favorite from t_model tm left join t_experiment_plan ep on tm.experiment_plan_id = ep.id and ep.is_deleted = 0 left join t_favorite f on tm.id = f.target_id and f.favorite_type = 'AGENT' and f.user_id = #{userId} and f.is_deleted = 0 where tm.is_delete = 0 and tm.model_status = 'OPEN'
and tm.attribution = #{attribution}
order by tm.update_date desc
